define(["core/ajax","core/templates","core/notification"],function(Ajax,Templates,Notification){const loadScript=(src,test)=>new Promise((resolve,reject)=>{if(test()){resolve();return}let settled=false;const waitForReady=()=>{const timer=window.setInterval(()=>{if(test()&&!settled){settled=true;window.clearInterval(timer);resolve()}},100);window.setTimeout(()=>{window.clearInterval(timer);if(!test()&&!settled){settled=true;reject(new Error(`Unable to load ${src}`))}},1e4)};const existing=document.querySelector(`script[src="${src}"]`);if(existing){waitForReady();return}const script=document.createElement("script");script.src=src;script.onload=waitForReady;script.onerror=()=>{if(!settled){settled=true;reject(new Error(`Unable to load ${src}`))}};document.head.appendChild(script)});const youtubeId=url=>{const match=String(url).match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([A-Za-z0-9_-]{6,})/);return match?match[1]:String(url).trim()};const vimeoId=url=>{const match=String(url).match(/vimeo\.com\/(?:video\/)?(\d+)/);return match?match[1]:String(url).trim()};const html5Adapter=(root,video,onTime)=>{root.replaceChildren();const element=document.createElement("video");element.controls=true;element.preload="metadata";element.playsInline=true;element.src=video.url;root.appendChild(element);element.addEventListener("timeupdate",()=>onTime(element.currentTime,!element.paused));return Promise.resolve({play:()=>element.play(),pause:()=>element.pause(),getTime:()=>Promise.resolve(element.currentTime||0),seek:seconds=>{element.currentTime=Math.max(0,seconds)},destroy:()=>{element.pause();element.remove()}})};const youtubeAdapter=async(root,video,onTime)=>{await loadScript("https://www.youtube.com/iframe_api",()=>typeof window.YT!=="undefined"&&typeof window.YT.Player!=="undefined");root.replaceChildren();const target=document.createElement("div");root.appendChild(target);return new Promise(resolve=>{let timer=null;const player=new window.YT.Player(target,{videoId:youtubeId(video.url),playerVars:{rel:0,playsinline:1},events:{onReady:()=>{timer=window.setInterval(()=>{onTime(player.getCurrentTime()||0,player.getPlayerState()===window.YT.PlayerState.PLAYING)},250);resolve({play:()=>player.playVideo(),pause:()=>player.pauseVideo(),getTime:()=>Promise.resolve(player.getCurrentTime()||0),seek:seconds=>player.seekTo(Math.max(0,seconds),true),destroy:()=>{if(timer){window.clearInterval(timer)}player.destroy()}})}}})})};const vimeoAdapter=async(root,video,onTime)=>{await loadScript("https://player.vimeo.com/api/player.js",()=>typeof window.Vimeo!=="undefined"&&typeof window.Vimeo.Player!=="undefined");root.replaceChildren();const iframe=document.createElement("iframe");iframe.src=`https://player.vimeo.com/video/${vimeoId(video.url)}`;iframe.allow="autoplay; fullscreen; picture-in-picture";iframe.allowFullscreen=true;iframe.className="videobranch-iframe";root.appendChild(iframe);const player=new window.Vimeo.Player(iframe);player.on("timeupdate",data=>onTime(data.seconds||0,true));player.on("pause",data=>onTime(data.seconds||0,false));return{play:()=>player.play(),pause:()=>player.pause(),getTime:()=>player.getCurrentTime(),seek:seconds=>player.setCurrentTime(Math.max(0,seconds)),destroy:()=>player.destroy()}};class Engine{constructor(root,config){this.root=root;this.config=config;this.playerRoot=root.querySelector('[data-region="player"]');this.overlay=root.querySelector('[data-region="overlay"]');this.pathRoot=root.querySelector('[data-region="path"]');this.pathCard=root.querySelector('[data-region="path-card"]');this.titleRoot=root.querySelector('[data-region="video-title"]');this.adapter=null;this.video=null;this.lastTime=0;this.maxAllowed=0;this.playing=false;this.decisionOpen=false;this.programmaticSeek=false;this.path=Array.isArray(config.attempt.path)?config.attempt.path:[];this.watched=config.attempt.watched||{};this.pendingSegments={};this.saveTimer=null;this.activeNodeIds=new Set(this.path.map(entry=>Number(entry.nodeid)))}async start(){this.pathCard.hidden=!this.config.showpath&&!this.config.allowback;this.renderPath();if(this.config.attempt.completed&&this.config.attempt.ending){await this.showEnding(this.config.attempt.ending);return}let videoid=Number(this.config.attempt.videoid)||Number(this.config.videos[0].id);let position=Number(this.config.attempt.position)||0;if(this.config.resumeplayback===0){videoid=Number(this.config.videos[0].id);position=0}else if(this.config.resumeplayback===2&&position>1){await new Promise(resolve=>{Notification.confirm(M.util.get_string("resumequestion","videobranch"),"",M.util.get_string("resumeyes","videobranch"),M.util.get_string("resumeno","videobranch"),resolve,()=>{position=0;resolve()})})}await this.loadVideo(videoid,position,false);this.saveTimer=window.setInterval(()=>this.saveState(),5e3);window.addEventListener("pagehide",()=>this.saveState())}async loadVideo(videoid,position,autoplay){const video=this.config.videos.find(item=>Number(item.id)===Number(videoid));if(!video||!video.url){Notification.exception(new Error(M.util.get_string("invalidvideo","videobranch")));return}if(this.adapter){this.adapter.destroy()}this.video=video;this.lastTime=Number(position)||0;this.maxAllowed=this.lastTime;this.titleRoot.textContent=video.name;const callback=(time,playing)=>this.onTime(time,playing);if(video.type==="youtube"){this.adapter=await youtubeAdapter(this.playerRoot,video,callback)}else if(video.type==="vimeo"){this.adapter=await vimeoAdapter(this.playerRoot,video,callback)}else{this.adapter=await html5Adapter(this.playerRoot,video,callback)}if(position>0){this.programmaticSeek=true;await Promise.resolve(this.adapter.seek(position));window.setTimeout(()=>{this.programmaticSeek=false},500)}if(autoplay){await Promise.resolve(this.adapter.play()).catch(()=>{})}}onTime(time,playing){time=Number(time)||0;if(!this.video||this.decisionOpen){return}if(!this.config.allowseek&&!this.programmaticSeek&&time>this.maxAllowed+2.5){this.programmaticSeek=true;Promise.resolve(this.adapter.seek(this.maxAllowed)).finally(()=>{window.setTimeout(()=>{this.programmaticSeek=false},300)});return}if(playing&&time>=this.lastTime&&time-this.lastTime<=2.5){this.addWatched(this.video.id,this.lastTime,time);this.maxAllowed=Math.max(this.maxAllowed,time)}const previous=this.lastTime;this.lastTime=time;this.playing=playing;const node=this.config.nodes.find(item=>Number(item.videoid)===Number(this.video.id)&&!this.activeNodeIds.has(Number(item.id))&&previous<Number(item.second)&&time>=Number(item.second));if(node){this.openDecision(node)}}addWatched(videoid,start,end){if(end<=start){return}const key=String(videoid);if(!this.pendingSegments[key]){this.pendingSegments[key]=[]}const list=this.pendingSegments[key];const last=list[list.length-1];if(last&&start<=last.end+.75){last.end=Math.max(last.end,end)}else{list.push({start:start,end:end})}}async openDecision(node){this.decisionOpen=true;await Promise.resolve(this.adapter.pause());const html=await Templates.render("mod_videobranch/decision",node);this.overlay.innerHTML=html;this.overlay.hidden=false;this.overlay.querySelectorAll('[data-action="choose"]').forEach(button=>{button.addEventListener("click",()=>this.choose(node,Number(button.dataset.optionid)))})}async choose(node,optionid){const buttons=this.overlay.querySelectorAll("button");buttons.forEach(button=>{button.disabled=true});try{await this.saveState();const response=await Ajax.call([{methodname:"mod_videobranch_choose_option",args:{cmid:this.config.cmid,nodeid:Number(node.id),optionid:optionid,videoid:Number(this.video.id),position:this.lastTime}}])[0];this.path=response.path||[];this.activeNodeIds=new Set(this.path.map(entry=>Number(entry.nodeid)));this.renderPath();this.overlay.hidden=true;this.overlay.replaceChildren();this.decisionOpen=false;if(response.type==="end"){this.config.attempt.completed=true;await this.showEnding({name:response.endingname,message:response.message});return}this.config.attempt.completed=false;this.maxAllowed=Number(response.second)||0;await this.loadVideo(Number(response.videoid),Number(response.second),true)}catch(error){buttons.forEach(button=>{button.disabled=false});Notification.exception(error)}}async rewind(choiceid){try{await this.saveState();const response=await Ajax.call([{methodname:"mod_videobranch_rewind_choice",args:{cmid:this.config.cmid,choiceid:Number(choiceid)}}])[0];this.path=response.path||[];this.activeNodeIds=new Set(this.path.map(entry=>Number(entry.nodeid)));this.renderPath();this.overlay.hidden=true;this.decisionOpen=false;this.config.attempt.completed=false;this.maxAllowed=Number(response.second)||0;await this.loadVideo(Number(response.videoid),Number(response.second),true)}catch(error){Notification.exception(error)}}async renderPath(){if(!this.config.showpath&&!this.config.allowback){return}const path=this.path.map(entry=>Object.assign({},entry,{allowback:this.config.allowback}));const html=await Templates.render("mod_videobranch/path",{path:path,allowback:this.config.allowback});this.pathRoot.innerHTML=html;this.pathRoot.querySelectorAll('[data-action="rewind"]').forEach(button=>{button.addEventListener("click",()=>this.rewind(Number(button.dataset.choiceid)))})}async showEnding(ending){if(this.adapter){await Promise.resolve(this.adapter.pause()).catch(()=>{})}const html=await Templates.render("mod_videobranch/ending",{name:ending.name,message:ending.message,showpath:this.config.showpath});this.overlay.innerHTML=html;this.overlay.hidden=false;this.decisionOpen=true;if(this.saveTimer){window.clearInterval(this.saveTimer)}}async saveState(){if(!this.video||!this.adapter||this.decisionOpen&&this.config.attempt.completed){return}try{const position=await this.adapter.getTime();const key=String(this.video.id);const segments=this.pendingSegments[key]||[];if(!segments.length&&Math.abs(Number(position)-Number(this.config.attempt.position))<.5){return}await Ajax.call([{methodname:"mod_videobranch_save_state",args:{cmid:this.config.cmid,videoid:Number(this.video.id),position:Number(position)||0,segments:segments}}])[0];this.pendingSegments[key]=[];this.config.attempt.position=Number(position)||0}catch(error){}}}const init=()=>{document.querySelectorAll('[data-region="videobranch"]').forEach(root=>{try{const config=JSON.parse(root.dataset.config||"{}");new Engine(root,config).start().catch(Notification.exception)}catch(error){Notification.exception(error)}})};return{init:init}});